mapper.select:
SELECT m.user_id FROM enterprise_member m JOIN app_user u ON u.id = m.user_id WHERE m.enterprise_id = #{scope.enterpriseId} AND
AND (LOCATE(#{query}, m.display_name) > 0 OR LOCATE(#{query}, COALESCE(u.email, '')) > 0)
AND m.status <> 'removed' AND m.status = #{status}
AND EXISTS (SELECT 1 FROM enterprise_team_member tm WHERE tm.enterprise_id = m.enterprise_id AND tm.user_id = m.user_id AND tm.team_id = #{teamId})
AND (m.joined_at < #{after.time} OR (m.joined_at = #{after.time} AND m.user_id < #{after.id}))
ORDER BY m.joined_at DESC, m.user_id DESC LIMIT #{count}

WHERE r.enterprise_id = #{enterprise} AND r.deleted_at IS NULL AND (LOCATE(#{query}, r.name) > 0 OR LOCATE(#{query}, r.code) > 0)
AND (r.created_at < #{after.time} OR (r.created_at = #{after.time} AND r.id < #{after.id}))
ORDER BY r.created_at DESC, r.id DESC LIMIT #{count}
